param(
    [Parameter(Mandatory = $true)]
    [string]$OriginalFile,
    
    [Parameter(Mandatory = $true)]
    [string]$FinalFile,
    
    [Parameter(Mandatory = $true)]
    [string]$ChangesFile
)

$timestamp = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
$resultDir = Join-Path (Resolve-Path "$PSScriptRoot\..\..\..\..") "result"
if (-not (Test-Path $resultDir)) {
    New-Item -ItemType Directory -Path $resultDir -Force | Out-Null
}

$original = Get-Content $OriginalFile -Raw
$final   = Get-Content $FinalFile -Raw
$changes = Get-Content $ChangesFile -Raw

$output = @"
# Humanize Result · $timestamp

---

## Original

$original

---

## Final Rewrite

$final

---

## Summary of Changes

$changes

---

*Generated by humanize-en skill on $timestamp*
"@

$outFile = Join-Path $resultDir "humanize-result-$timestamp.md"
Set-Content -Path $outFile -Value $output -Encoding UTF8
Write-Output "Result saved to: $outFile"
